"""The settings page in plain words: for each setting (procintel.api.config) a label, a group and one or two sentences
saying what it does and what changing it means. The technical description stays in config.py and is shown behind the
page's (i) button. Grouped by what a person would look for: Models, Search, Answer checks, Assessment, Background work,
Passages."""

# key -> (label, group, plain note)
PLAIN = {
 "llm_model": ("Answer model", "Models", "The AI model that reads the evidence and writes answers and plans. Empty: answers are quoted sentences from the reports, with no model writing."),
 "llm_api_base": ("Answer model address", "Models", "Where the answer model runs. Only change it when the model moves to another server."),
 "llm_extra_body": ("Answer model extra options", "Models", "Extra switches some model servers need. Leave as it is unless the model's documentation asks for one."),
 "llm_temperature": ("Answer creativity", "Models", "How much the answer model varies its wording. 0 gives the same answer every time, which suits evidence-based answers."),
 "llm_max_tokens": ("Longest answer (tokens)", "Models", "The most the answer model may write in one reply, in tokens: a token is about three quarters of a word, so 1,200 is about 900 words. A cited answer uses a few hundred. A reply that hits this limit is treated as failed rather than shown half-finished. A hosted model (Claude) can take 2,000 to 4,000; a local one also has to fit the question and passages in its own context (Saluki: 8,192)."),
 "judge_model": ("Second checking model", "Models", "Used only when measuring quality: a different model double-checks that answer sentences match their sources, so the answer model does not grade itself. Empty: no second check."),
 "judge_api_base": ("Second checking model address", "Models", "Where the second checking model runs."),
 "judge_extra_body": ("Second checking model extra options", "Models", "Extra switches for that model's server. Leave as it is unless needed."),
 "batch_model": ("Model for background work", "Models", "The model used for work nobody waits for (tagging passages, measuring quality). Empty: the answer model. Background work waits only while a user's request is using the same model."),
 "batch_api_base": ("Model for background work: address", "Models", "Where that model runs. Empty: the same place as the answer model."),
 "batch_extra_body": ("Model for background work: extra options", "Models", "Extra switches for that model's server. Leave as it is unless needed."),
 "decide_api_base": ("Quick checking model address", "Models", "A small, fast model that checks each passage and each answer sentence (relevant? supported?). Empty: those checks fall back to matching words."),
 "embed_model": ("Search model (meaning)", "Models", "The model that turns passages into numbers so search can find text with the same meaning in other words. Shown for information: changing it means re-processing every passage."),
 "embed_dim": ("Search model size", "Models", "How detailed those numbers are. Shown for information, for the same reason."),
 "search_k": ("Passages looked at per question", "Search", "How many passages search hands over for checking before an answer is written. More can find more, but answers take longer."),
 "pool": ("Candidates from each search method", "Search", "Search runs two ways, by keywords and by meaning; this is how many results each one contributes before they are combined."),
 "rrf_k": ("How the two searches are combined", "Search", "Controls how much the very top results of each search count compared with lower ones. 60 is the standard value; rarely worth changing."),
 "min_evidence": ("Search again when evidence is thin", "Search", "If fewer than this many useful passages are found, the question is reworded and searched again. 0 turns this off."),
 "clarify": ("Tidy up questions first", "Search", "1: a casual or unclear question is rewritten as a clear one before searching (about 2 seconds). 0: the question is used as typed."),
 "vocab_step": ("Also search in the reports' own words", "Search", "1: each question is also rephrased in the vocabulary World Bank reports use, and both versions are searched (about 2 seconds). 0: only when evidence is thin."),
 "max_passages": ("Passages used for one answer", "Answer checks", "How many checked passages the answer model reads and may cite."),
 "llm_gate": ("Who decides which passages are evidence", "Answer checks", "1: the answer model chooses, more precise but slower (about 14 seconds). 0: the quick checking model judges each passage (under a second)."),
 "decide_min": ("How sure the quick check must be", "Answer checks", "A passage counts as relevant, and a sentence as supported, only when the quick checking model is at least this sure. Higher is stricter: fewer but safer answers."),
 "grounding_min": ("Word match needed without the quick check", "Answer checks", "Used only if the quick checking model is off: the share of a sentence's words that must appear in the passage it cites."),
 "not_a_lesson_min": ("Hide passages that are not lessons", "Assessment", "Passages a model judged to describe no problem are left out of the lessons on the assessment page when it is at least this sure. 1 shows everything."),
 "jobs_idle_seconds": ("Free time before background work uses a model", "Background work", "Background work starts once the models it needs have served no user for this many seconds, and pauses after its current step when a user needs one of them, so it never slows anyone down."),
 "jobs_max_wait_seconds": ("Longest background work waits", "Background work", "If the app is busy all day, background work starts anyway after waiting this long."),
 "demote_min": ("Flags before a wrong citation is pushed down", "Background work", "When this many separate users flag the same passage as a wrong citation, search moves it to the bottom of its results."),
 "drift_min_new": ("New packages needed to check the forecast", "Background work", "The forecast model is only re-checked once at least this many new awarded packages have come in since it was trained."),
 "drift_growth": ("Retrain after this much new data", "Background work", "Retrain the forecast model when the new packages reach this share of the data it was trained on (0.2 = 20%)."),
 "drift_error_ratio": ("Retrain when the forecast gets worse", "Background work", "Retrain when the forecast's error on new packages is this many times its usual error."),
 "retention_days": ("Keep history for (days)", "Background work", "Logs, finished jobs and other history older than this are deleted every day."),
 "pilot_until": ("Pilot end date", "Background work", "During a pilot, usage logs and feedback are kept in full so the pilot's results can be measured. Empty: no pilot."),
 "chunk_max_chars": ("Longest passage (characters)", "Passages", "Reports are cut into passages for search; a paragraph longer than this is split. Applies at the next data refresh."),
 "flat_numbers": ("Table detection: share of numbers", "Passages", "For reports whose tables could not be read from the PDF: a passage with at least this share of numbers is treated as a table and not used for answers."),
 "flat_numbers_no_sentence": ("Table detection: numbers without sentences", "Passages", "The same rule for passages with almost no full sentences, which needs fewer numbers."),
 "caption_numbers": ("Table detection: captioned tables", "Passages", "A passage that starts with a caption like \"Table 4.\" and has at least this share of numbers is treated as a table."),
}
